function prepareHighSchoolYearOneMatch(options = {}) {
  assertHighSchoolMatchCapabilityAdmission(player);
  if (options.matchContext && typeof MatchContextFoundation === "undefined") throw new Error("Explicit match context requires MatchContextFoundation");
  const targetMatchId = options.matchId || "hs-y1-autumn-exhibition";
  const targetEventId = options.eventId || "high_school_showcase";
  const highSchoolYear = Math.max(1, Math.min(3, Math.floor(Number(options.highSchoolYear) || 1)));
  const opportunityIndex = Math.max(1, Number(options.opportunityIndex) || 1);
  if (player.highSchoolMatch?.id === targetMatchId) {
    const match = player.highSchoolMatch;
    if (options.matchContext) {
      if (!match.matchContext) throw new Error("Existing match has no explicit context; cannot reassign a started match");
      const requested = MatchContextFoundation.normalizeMatchContext({...match.matchContext, ...options.matchContext});
      if (JSON.stringify(requested) !== JSON.stringify(match.matchContext)) throw new Error("Existing match context cannot change");
    }
    if (match.completed || (typeof match.simulationPhase === "string" && match.rosters?.home?.lineup?.length === 9 && match.rosters?.away?.lineup?.length === 9)) {
      match.currentMomentId = getHighSchoolYearOneMomentId(match);
      if (!match.completed && match.currentDomain === "defense" && isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.position) && match.defensiveSituation?.familyId !== "infield") {
        buildInfieldMeaningfulMoment(match, player);
        match.currentAssignment = getHighSchoolDefensiveSituationText(match);
        setHighSchoolCoachTacticalDirection(match);
      }
      return match;
    }
  }
  const code = ["starter", "rotation", "bench"].includes(player.highSchoolRoleCode) ? player.highSchoolRoleCode : "bench";
  if (highSchoolYear === 1 && !player.highSchoolYearOneStartingRole) player.highSchoolYearOneStartingRole = code;
  const roleAssignments = {
    starter: { lineupStatus: "starter", entryWindowInning: 1, history: `以${player.primaryPosition || "守備"}先發，從開賽起進入守備與打序` },
    rotation: { lineupStatus: "bench", entryWindowInning: 4, history: `本場先從板凳待命，預計在中段代打並接替${player.primaryPosition || "守備"}` },
    bench: { lineupStatus: "bench", entryWindowInning: 5, history: `本場先從板凳觀察，等待中後段代打與短局守備機會` }
  };
  const position = player.primaryPosition || "內野手";
  const requestedDevelopmentPosition = opportunityIndex === 1 && infieldPositions.includes(pendingHighSchoolMatchPositionOverride)
    ? pendingHighSchoolMatchPositionOverride : "";
  if (requestedDevelopmentPosition && !isDevelopmentTestPositionLegalForThrowingHand(requestedDevelopmentPosition, player.throws, player.age)) {
    throw new Error(getDevelopmentTestPositionLegalityMessage(requestedDevelopmentPosition, player.throws));
  }
  const developmentPositionOverride = requestedDevelopmentPosition;
  const suppliedOpportunity = options.opportunityDecision || null;
  const simulationSeed = suppliedOpportunity
    ? createHighSchoolMatchSimulationSeedFromIdentity(suppliedOpportunity.decisionId || suppliedOpportunity.matchId)
    : createHighSchoolMatchSimulationSeed();
  const directStartForced = highSchoolYear === 1 && opportunityIndex === 1
    && Array.isArray(player.flags) && player.flags.includes("direct_start_history");
  const opportunityDecision = suppliedOpportunity || createHighSchoolPlayingTimeOpportunity({
    matchId: targetMatchId,
    actualRole: code,
    requestedPosition: developmentPositionOverride || position,
    directStartForced,
    opportunityIndex,
    opportunityPhase: options.opportunityPhase || "autumn-exhibition",
    highSchoolYear
  });
  if ((suppliedOpportunity || opportunityIndex > 1) && (!opportunityDecision || opportunityDecision.matchId !== targetMatchId)) {
    throw new Error(`高中第 ${highSchoolYear} 年第 ${opportunityIndex} 次實戰必須直接消費相同 match identity 的既有 Opportunity。`);
  }
  if (opportunityDecision && typeof HighSchoolCompetitionReassessment !== "undefined") {
    player.highSchoolOpportunityHistory = HighSchoolCompetitionReassessment.recordOpportunity(player.highSchoolOpportunityHistory, {
      opportunity: opportunityDecision,
      opportunityIndex,
      roleAtCreation: code
    });
  }
  const plannedAppearance = opportunityDecision?.plannedUsage?.appearanceType || (code === "starter" ? "start" : "lateGameAppearance");
  const starts = plannedAppearance === "start";
  const roleAssignment = opportunityDecision
    ? {
      lineupStatus: starts ? "starter" : "bench",
      entryWindowInning: starts ? 1 : Math.max(5, Number(opportunityDecision.plannedUsage.entryInning) || 5),
      history: getHighSchoolPlayingTimeAssignmentText(opportunityDecision)
    }
    : roleAssignments[code];
  const assignedPosition = opportunityDecision?.assignedPosition || developmentPositionOverride || position;
  const developmentTestCapabilityOverride = developmentPositionOverride
    ? createDevelopmentMatchPositionTestCapabilityOverride(developmentPositionOverride, player) : null;
  const selectedSchoolRoster = materializeSelectedHighSchoolRoster(player, {
    rosterRole: starts ? "starter" : "bench",
    playerPosition: assignedPosition
  });
  const rosters = createHighSchoolMatchSimulationRoster(
    starts ? "starter" : code === "starter" ? "bench" : code,
    assignedPosition,
    simulationSeed,
    selectedSchoolRoster,
    options.opponentRosterId || "regional-power-school"
  );
  const matchContext = typeof MatchContextFoundation !== "undefined" ? MatchContextFoundation.createMatchContext({
    matchId: targetMatchId,
    playerTeamId: rosters.home.teamRoster?.teamId || "home",
    opponentTeamId: rosters.away.teamRoster?.teamId || "away",
    matchOrigin: options.matchType === "final-competition" ? "officialCompetition" : "developmentMatch",
    legacyFallback: !options.matchContext,
    ...options.matchContext
  }) : null;
  if (matchContext && (matchContext.matchId !== targetMatchId || matchContext.playerTeamId !== (rosters.home.teamRoster?.teamId || "home") || matchContext.opponentTeamId !== (rosters.away.teamRoster?.teamId || "away"))) throw new Error("Match context / roster identity mismatch");
  if (matchContext && MatchContextFoundation.isPlayerAway(matchContext)) [rosters.home, rosters.away] = [rosters.away, rosters.home];
  const playerSide = matchContext ? MatchContextFoundation.playerSide(matchContext) : "home";
  const playerLineupSlot = rosters[playerSide].lineup.findIndex(item => item.id === "player");
  const resolvedCompetitionRules = typeof CompetitionRules !== "undefined"
    ? CompetitionRules.resolveMatchCompetitionRules(matchContext)
    : null;
  const regulationInnings = resolvedCompetitionRules?.rules.regulationInnings
    || Math.max(1, Number(player.highSchoolMatch?.regulationInnings) || 7);
  player.highSchoolMatch = {
    id: targetMatchId,
    matchContext,
    ...(resolvedCompetitionRules ? {
      ruleSetId: resolvedCompetitionRules.ruleSetId,
      rules: resolvedCompetitionRules.rules,
      ruleSetWarning: resolvedCompetitionRules.warning
    } : {}),
    ...(options.scheduleCompetitionRefs || {}),
    eventId: targetEventId,
    matchType: options.matchType || "autumn-exhibition",
    highSchoolYear,
    opportunityIndex,
    opponent: options.opponent || "高橋所屬的地區強校",
    inning: 1,
    half: "上",
    outs: 0,
    scores: { home: 0, away: 0 },
    runners: [null, null, null],
    role: code,
    position,
    assignment: roleAssignment.history,
    matchEntryHistory: `${roleAssignment.history}；${formatHandedness(player.bats, player.throws)}`,
    currentAssignment: starts ? (playerSide === "home" ? "比賽從一局上開始；先完成守備，再等待打序輪到你。" : "比賽從一局上開始；依打序完成進攻，再進入守備。") : "比賽從一局上開始；你在板凳觀察，但場上每個打席都會完整進行。",
    offenseTeam: "away",
    defenseTeam: "home",
    currentBatter: rosters.away.lineup[0]?.id || "",
    battingOrderIndex: { home: 0, away: 0 },
    tiebreakHalfInitialization: null,
    halfInningResolved: false,
    simulationPhase: "full_match_flow",
    simulationCursor: 0,
    simulationSeed,
    simulationLog: [],
    presentedEventCursor: 0,
    scoreboardRevealHalfIndex: 0,
    regulationInnings,
    lineScore: { home: [], away: [] },
    gameRecord: null,
    rosters,
    playerLineupStatus: roleAssignment.lineupStatus,
    playerLineupSlot,
    playerFieldingAssignment: starts ? assignedPosition : "",
    playerEntryWindowInning: roleAssignment.entryWindowInning,
    playerEntryCompleted: starts,
    performanceEvidence: {},
    matchExperience: null,
    gameExposureState: opportunityDecision && typeof PlayingTimeGameExposure !== "undefined"
      ? PlayingTimeGameExposure.createGameExposureState(opportunityDecision) : null,
    developmentFullMatchStart: pendingHighSchoolFullMatchTest,
    playerRunnerLocation: -1,
    momentIndex: 0,
    currentMomentId: highSchoolYearOneMomentIds[0],
    currentDomain: "flow",
    coachTacticalDirection: { domain: "", intent: "", riskPreference: "", priority: "", sourceCoachId: "", presentationStyle: "" },
    coachTacticalContextSignature: "",
    opponentTacticalTruth: { code: "", targetRunnerId: "" },
    ballContext: { type: "", family: "", pace: "", label: "", detail: "", timeWindow: "" },
    positionDecisionFamily: "", currentFieldingPosition: starts && (developmentPositionOverride || opportunityDecision?.positionFallbackApplied) ? assignedPosition : "", developmentPositionOverride,
    developmentTestCapabilityOverride, defensiveSituation: {},
    matchDecisionDensityState: createHighSchoolMatchDecisionDensityState(),
    pitcherRuntimeState: null,
    pitcherSequencingDebugTrace: [],
    pitcherObservableHistory: [],
    pitcherTacticalSequenceHistory: [],
    pitcherTacticalDebugTrace: [],
    batterAnticipationState: null,
    prePitchPlanningState: null,
    offensivePlateAppearanceState: null,
    pendingOffensiveOpportunity: null,
    offensivePlayerAgencyState: null,
    offensiveTacticalActionState: null,
    offensiveBuntPAState: null,
    buntBallInPlayState: null,
    pendingDefensiveResumeState: null,
    lastDefensiveResolution: { resultCode: "", tier: "", decisionQuality: "", executionQuality: "", primaryCause: "", secondaryCause: "", causeExplanation: "" },
    pendingHalfInningTermination: null,
    catcherDecisionState: null,
    catcherReassessmentTrigger: null,
    completedMoments: [],
    playerContribution: { strong: 0, mixed: 0, failure: 0, runsCreated: 0, runsScored: 0, hits: 0, walks: 0, outsCreated: 0, errors: 0 },
    previousMomentDecision: "",
    previousMomentOutcome: "",
    passage: "",
    opponentAdjustment: "",
    coachInstruction: starts ? "先跟著比賽完成每個守備與打席。" : "先讀完整比賽流；被叫到時直接接進當下局面。",
    decision: "",
    outcomeTier: "",
    outcome: "",
    consequence: "",
    coachReaction: "現任教練確認你的第一個場上任務。",
    teamReaction: "休息區把下一段比賽交到你手上。",
    performanceSummary: "",
    teamResult: "",
    settled: false,
    pendingGameSettlement: "",
    eventSettlementApplied: false,
    developmentPresentationCompleted: false,
    completed: false
  };
  ensureHighSchoolPitcherRuntimeState(player.highSchoolMatch);
  if (isHighSchoolMatchOpportunityDebugMode()) ensureHighSchoolMatchOpportunityTrace(player.highSchoolMatch);
  setHighSchoolCoachTacticalDirection(player.highSchoolMatch);
  recordHighSchoolMatchSimulationEvent(player.highSchoolMatch, {
    type: "matchEntry", inning: 1, half: "上",
    outs: 0, runners: player.highSchoolMatch.runners,
    scores: player.highSchoolMatch.scores,
    assignment: player.highSchoolMatch.matchEntryHistory
  });
  pendingHighSchoolMatchPositionOverride = "";
  pendingHighSchoolFullMatchTest = false;
  player.highSchoolRoleContext.assignment = roleAssignment.history;
  return player.highSchoolMatch;
}

function prepareCurrentHighSchoolYearOneMatch() {
  if (getCurrentEventId() === "critical_tournament" && isCanonicalHighSchoolYearThreeRoute()) return prepareHighSchoolYearThreeMatch();
  if (getCurrentEventId() === "high_school_year_two_autumn_stage" && isHighSchoolYearOneMatchEventId("high_school_year_two_autumn_stage")) {
    return prepareHighSchoolYearTwoAutumnMatch();
  }
  if (getCurrentEventId() === "high_school_year_two_spring_game" && isHighSchoolYearOneMatchEventId("high_school_year_two_spring_game")) {
    return prepareHighSchoolYearTwoEvaluationMatch();
  }
  return getCurrentEventId() === "high_school_followup_evaluation"
    ? prepareHighSchoolFollowupEvaluationMatch()
    : prepareHighSchoolYearOneMatch();
}

function launchHighSchoolScheduleEntry(scheduleEntryId, options) {
  assertHighSchoolMatchCapabilityAdmission(player);
  const state = player.highSchoolSchedule;
  const requestedEntry = state?.entries.find(item => item.scheduleEntryId === scheduleEntryId);
  if (!requestedEntry || !["scheduled", "inProgress"].includes(requestedEntry.status)) throw new Error("Schedule entry cannot launch");
  const context = getHighSchoolScheduleExecutionContext();
  const entry = HighSchoolScheduleOpportunity.assertCanLaunch(state,scheduleEntryId,context,player.highSchoolMatch);
  if (entry.status === "inProgress") return player.highSchoolMatch;
  const matchId = options.matchId;
  if (player.highSchoolMatch?.id === matchId || [1,2,3].some(year => {
    const key = ["", "highSchoolYearOneMatchHistory", "highSchoolYearTwoMatchHistory", "highSchoolYearThreeMatchHistory"][year];
    return (player[key] || []).some(item => item.matchId === matchId);
  })) throw new Error("Schedule cannot reuse an existing match identity");
  const matchContext = HighSchoolScheduleOpportunity.deriveMatchContextInput(state,scheduleEntryId,matchId);
  const scheduleCompetitionRefs = getHighSchoolScheduleCompetitionRefs(state.opportunities.find(item => item.opportunityId === entry.opportunityId));
  MatchContextFoundation.createMatchContext(matchContext);
  const match = prepareHighSchoolYearOneMatch({...options, highSchoolYear:entry.careerYear,
    opportunityPhase:entry.seasonPhase, opponentRosterId:entry.opponentSchoolId, matchContext, scheduleCompetitionRefs});
  HighSchoolScheduleOpportunity.markScheduleStarted(state,scheduleEntryId,match);
  return match;
}

function createHighSchoolMatchSimulationRoster(role, playerPosition, simulationSeed = 1, selectedHomeRoster = null, opponentIdentity = "regional-power-school") {
  if (typeof TeamRosterFoundation === "undefined" || typeof TeamStrengthModel === "undefined") {
    return createLegacyHighSchoolMatchSimulationRoster(role, playerPosition);
  }
  const selectedSchool = getSelectedHighSchoolContext(player);
  const playerRole = role === "starter" ? "starter" : "bench";
  const playerActor = createHighSchoolRosterPlayerActor(player, playerPosition);
  const homeRoster = selectedHomeRoster && TeamRosterFoundation.validateRoster(selectedHomeRoster).ok
    ? selectedHomeRoster
    : TeamRosterFoundation.generateTeamRoster({
      teamId: selectedSchool?.schoolId || "home-school", schoolId: selectedSchool?.schoolId || "home-school",
      schoolStandard: selectedSchool?.schoolTier || "standard", yearIdentity: `hs-y1-${player.age || 15}`,
      seed: `${simulationSeed}|home`, playerActor, playerRole, playerPosition
    });
  const awayRoster = TeamRosterFoundation.generateTeamRoster({
    teamId: opponentIdentity, schoolId: opponentIdentity, schoolStandard: "competitive",
    yearIdentity: `hs-y1-${player.age || 15}`, seed: `${simulationSeed}|away`
  });
  const homeStrength = TeamStrengthModel.deriveTeamStrengthProfile(homeRoster);
  const awayStrength = TeamStrengthModel.deriveTeamStrengthProfile(awayRoster);
  return {
    home: TeamRosterFoundation.toMatchRoster(homeRoster, homeStrength),
    away: TeamRosterFoundation.toMatchRoster(awayRoster, awayStrength)
  };
}

function materializeSelectedHighSchoolRoster(subject = player, options = {}) {
  if (typeof HighSchoolEntryRosterContext === "undefined" || typeof TeamRosterFoundation === "undefined") return null;
  const state = subject?.schoolInvitationState;
  const invitation = getSelectedSchoolInvitation(subject);
  const baseRoster = state?.selectedBaseRoster || invitation?.baseRoster;
  if (!baseRoster || !TeamRosterFoundation.validateRoster(baseRoster).ok) return null;
  const invitationPosition = invitation?.positionCompetitionContext?.position || invitation?.schoolInterest?.candidatePosition || "";
  const rawPosition = options.playerPosition || subject?.primaryPosition || invitationPosition;
  const normalizedRequested = TeamRosterFoundation.normalizePosition(rawPosition);
  const requestedPosition = ["內野手", "外野手"].includes(rawPosition) && invitationPosition
    ? TeamRosterFoundation.normalizePosition(invitationPosition) : normalizedRequested;
  const rosterRole = options.rosterRole === "starter" ? "starter" : "bench";
  const selectedRoster = HighSchoolEntryRosterContext.injectPlayerIntoSelectedRoster(
    baseRoster,
    createHighSchoolRosterPlayerActor(subject, requestedPosition),
    { playerRole: rosterRole, playerPosition: requestedPosition }
  );
  const playerCapability = HighSchoolEntryRosterContext.getPositionCapability(
    selectedRoster.players.find(actor => actor.id === "player"), requestedPosition
  );
  const invitationCompetition = invitation?.positionCompetitionContext;
  const competition = options.refreshCompetition !== true && invitationCompetition?.position === requestedPosition
    ? cloneSchoolInvitationValue(invitationCompetition)
    : HighSchoolEntryRosterContext.deriveCompetitionContext(baseRoster, requestedPosition, playerCapability);
  const activeRosterIdentity = state.selectedSchoolYearRosterIdentity || invitation.schoolYearRosterIdentity;
  state.selectedSchoolYearRosterIdentity = cloneSchoolInvitationValue(activeRosterIdentity);
  state.selectedBaseRoster = cloneSchoolInvitationValue(baseRoster);
  state.selectedSchoolRoster = cloneSchoolInvitationValue(selectedRoster);
  state.selectedPositionCompetitionContext = cloneSchoolInvitationValue(competition);
  state.selectedPlayerInjectionState = {
    ...cloneSchoolInvitationValue(selectedRoster.playerInjection),
    status: "injected",
    schoolYearRosterIdentity: activeRosterIdentity.identity
  };
  return selectedRoster;
}

function createHighSchoolPlayingTimeOpportunity(options = {}) {
  if (typeof PlayingTimeGameExposure === "undefined") return null;
  const requestedPosition = options.requestedPosition || player.primaryPosition || "內野手";
  const school = getHighSchoolPlayingTimeSchoolContext(player);
  const readinessSnapshot = createHighSchoolOpportunityReadinessSnapshot(requestedPosition, player);
  const opportunityIndex = Math.max(1, Number(options.opportunityIndex) || 1);
  const schoolYearIdentity = player.schoolInvitationState?.selectedSchoolYearRosterIdentity?.identity
    || `${school.schoolId}|legacy-high-school-year-one`;
  const highSchoolYear = Math.max(1, Math.min(3, Math.floor(Number(options.highSchoolYear) || 1)));
  const yearPhase = highSchoolYear === 1 ? "high-school-year-one" : `high-school-year-${highSchoolYear}`;
  const opportunityPhase = options.opportunityPhase || (opportunityIndex === 1 ? "autumn-exhibition" : "post-autumn-evaluation");
  const resolved = PlayingTimeGameExposure.resolveStartingOpportunity({
    matchId: options.matchId,
    readinessSnapshot,
    opportunitySeed: [player.capabilityState?.settlementId || player.capabilityState?.version || "capability", schoolYearIdentity, yearPhase, opportunityPhase, opportunityIndex, options.matchId || "match"].join("|"),
    actualRole: options.actualRole,
    projectedRole: school.projectedRole,
    playingTimeEnvironment: school.playingTimeEnvironment,
    competitionDepth: school.competitionDepth,
    positionNeed: school.positionNeed,
    coachUsageStyle: school.coachStyle,
    evaluationTrend: options.evaluationTrend,
    previousActualExposure: options.previousActualExposure,
    coachTrust: options.includeDynamicReadiness ? player.relationships?.coachTrust : undefined,
    health: options.includeDynamicReadiness ? player.body : undefined,
    stableVariationSeed: options.stableVariationSeed,
    directStartForced: options.directStartForced === true,
    gameContext: { gameType: "highSchoolExhibition", inning: 0, expectedGameImportance: "regular", importance: "regular", leverage: "normal", scoreMargin: 0 }
  });
  if (!options.preserveDecisionId) return resolved;
  return Object.freeze({
    ...cloneSchoolInvitationValue(resolved),
    decisionId: options.preserveDecisionId,
    opportunitySeed: options.preserveOpportunitySeed || resolved.opportunitySeed
  });
}

function insertPlayerIntoHighSchoolMatchLineup(match) {
  const lineup = match.rosters?.[getHighSchoolPlayerTeamSide(match)]?.lineup;
  const bench = match.rosters?.[getHighSchoolPlayerTeamSide(match)]?.bench;
  if (typeof TeamRosterFoundation !== "undefined") TeamRosterFoundation.assertActiveDefense(match.rosters?.[getHighSchoolPlayerTeamSide(match)]);
  if (!Array.isArray(lineup)) return false;
  const existingSlot = lineup.findIndex(item => item.id === "player");
  if (existingSlot >= 0) {
    match.playerLineupSlot = existingSlot;
    return false;
  }
  const slot = Math.max(0, Math.min(8, Number(match.battingOrderIndex?.[getHighSchoolPlayerTeamSide(match)]) || 0));
  const replaced = lineup[slot];
  const assignedPosition = match.gameExposureState?.opportunitySnapshot?.assignedPosition
    || match.developmentPositionOverride || match.playerFieldingAssignment || match.position;
  const incumbent = getCurrentHighSchoolMatchDefender(match, getHighSchoolPlayerTeamSide(match), assignedPosition);
  if (!incumbent) throw new Error("Active defense integrity failed: missing substitution incumbent");
  if (incumbent !== replaced) return false;
  const benchPlayer = (bench || []).find(item => item.id === "player");
  if (!benchPlayer) throw new Error("Active defense integrity failed: incoming player not on bench");
  const incoming = { ...benchPlayer, id: "player", name: player.name || "你",
    position: replaced.position, defensivePosition: replaced.defensivePosition,
    bats: player.bats, throws: player.throws, age: player.age, source: "canonical-player" };
  const nextRoster = { ...match.rosters[getHighSchoolPlayerTeamSide(match)], lineup: lineup.map((actor, index) => index === slot ? incoming : actor),
    bench: [...(bench || []).filter(item => item.id !== "player"), replaced] };
  if (typeof TeamRosterFoundation !== "undefined") TeamRosterFoundation.assertActiveDefense(nextRoster);
  match.rosters[getHighSchoolPlayerTeamSide(match)] = nextRoster;
  match.playerLineupSlot = slot;
  return { slot, replaced };
}

function enterHighSchoolMatchPlayer(match) {
  assertHighSchoolMatchCapabilityAdmission(player);
  if (!shouldEnterHighSchoolMatchPlayer(match)) return false;
  const entryTruth = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
  const insertion = insertPlayerIntoHighSchoolMatchLineup(match);
  if (!insertion) return false;
  match.playerLineupStatus = "substitute";
  match.playerEntryCompleted = true;
  match.playerFieldingAssignment = match.gameExposureState?.opportunitySnapshot?.assignedPosition || match.developmentPositionOverride || match.position;
  match.currentFieldingPosition = match.playerFieldingAssignment;
  match.currentBatter = "player";
  const plannedAppearance = match.gameExposureState?.plannedUsage?.appearanceType || "lateGameAppearance";
  const entryLabel = !match.gameExposureState ? "叫你代打"
    : plannedAppearance === "defensiveSubstitution" ? "準備接替守備，並先從這個打席進入比賽"
    : plannedAppearance === "pinchHit" ? "叫你代打" : "叫你進入比賽";
  match.matchEntryHistory = `${match.inning}局${match.half}${match.outs}出局時，教練${entryLabel}；進場比分與壘況沿用當下比賽。`;
  match.currentAssignment = `${formatHighSchoolMatchRunners(match.runners)}、${match.outs} 出局；你從板凳進入第 ${insertion.slot + 1} 棒。`;
  setHighSchoolCoachTacticalDirection(match);
  const event = recordHighSchoolMatchSimulationEvent(match, {
    type: "playerEntry", inning: entryTruth.inning, half: entryTruth.half,
    lineupSlot: insertion.slot, replacedPlayerId: insertion.replaced?.id || "", plannedAppearanceType: plannedAppearance,
    assignment: match.currentAssignment, outs: entryTruth.outs, scores: entryTruth.scores, runners: entryTruth.runners
  });
  recordHighSchoolMatchOpportunityCheckpoint("player-entry", match, {
    lineupSlot: insertion.slot,
    entry: { inning: entryTruth.inning, half: entryTruth.half, outs: entryTruth.outs, scores: entryTruth.scores, runners: entryTruth.runners }
  });
  return event;
}

function shouldEnterHighSchoolMatchPlayer(match) {
  if (match && !match.playerEntryCompleted && match.playerLineupStatus === "bench") {
    const assignedPosition = match.gameExposureState?.opportunitySnapshot?.assignedPosition
      || match.developmentPositionOverride || match.playerFieldingAssignment || match.position;
    const incumbent = getCurrentHighSchoolMatchDefender(match, getHighSchoolPlayerTeamSide(match), assignedPosition);
    if (!incumbent) throw new Error("Active defense integrity failed: missing substitution incumbent");
    if (match.rosters[getHighSchoolPlayerTeamSide(match)].lineup[Number(match.battingOrderIndex?.[getHighSchoolPlayerTeamSide(match)]) || 0] !== incumbent) return false;
  }
  const exposureState = match?.gameExposureState;
  if (exposureState) {
    if (exposureState.pitcherExposureDeferred || exposureState.plannedUsage?.appearanceType === "noAppearance") return false;
    const opportunity = exposureState.opportunitySnapshot || {};
    const margin = Math.abs(getHighSchoolPlayerScoreDifference(match));
    const coachStyle = opportunity.coachUsageStyle || "balanced";
    const actualRole = opportunity.actualRole || match.role || "bench";
    const contextAllowsEntry = coachStyle === "developmental"
      || actualRole === "starter"
      || (coachStyle === "conservative" ? margin >= 3 : coachStyle === "performanceFirst" ? actualRole === "rotation" || margin <= 2 : actualRole === "rotation" || margin >= 2);
    if (!contextAllowsEntry || match.inning < 5) return false;
  }
  return Boolean(match && !match.playerEntryCompleted && match.playerLineupStatus === "bench"
    && match.offenseTeam === getHighSchoolPlayerTeamSide(match)
    && match.inning >= Math.max(1, Number(match.playerEntryWindowInning) || 1)
    && match.outs < 3);
}

function getCurrentHighSchoolMatchDefender(match, team, position) {
  const roster = match?.rosters?.[team];
  if (typeof TeamRosterFoundation !== "undefined") return TeamRosterFoundation.getCurrentDefender(roster, position);
  // Compatibility for isolated legacy harnesses without the canonical roster module.
  const candidates = (roster?.lineup || []).filter(actor => actor.position === position);
  return candidates.length === 1 && !(roster?.bench || []).some(actor => actor.id === candidates[0].id) ? candidates[0] : null;
}

function getHighSchoolMatchLineupBatter(match, team) {
  const lineup = match.rosters?.[team]?.lineup || [];
  const index = Math.max(0, Number(match.battingOrderIndex?.[team]) || 0) % Math.max(1, lineup.length);
  return lineup[index] || null;
}

function advanceHighSchoolMatchBattingOrder(match, team) {
  const lineupLength = Math.max(1, match.rosters?.[team]?.lineup?.length || 9);
  match.battingOrderIndex[team] = ((Number(match.battingOrderIndex?.[team]) || 0) + 1) % lineupLength;
  match.currentBatter = getHighSchoolMatchLineupBatter(match, team)?.id || "";
}

function getHighSchoolMatchStateIntegrityIssues(match) {
  const issues = [];
  const outs = Number(match?.outs);
  if (!Number.isInteger(outs) || outs < 0 || outs > 3) issues.push("outs-out-of-range");
  const runners = Array.isArray(match?.runners) ? match.runners.slice(0, 3).filter(Boolean) : [];
  if (new Set(runners).size !== runners.length) issues.push("duplicate-runner-identity");
  if (!match?.completed && ["上", "下"].includes(match?.half)) {
    const expectedOffense = match.half === "上" ? "away" : "home";
    const expectedDefense = expectedOffense === "away" ? "home" : "away";
    if (match.offenseTeam !== expectedOffense) issues.push("offense-half-mismatch");
    if (match.defenseTeam !== expectedDefense) issues.push("defense-half-mismatch");
    if (match.offenseTeam === match.defenseTeam) issues.push("team-role-collision");
    const expectedBatter = getHighSchoolMatchLineupBatter(match, match.offenseTeam)?.id || "";
    if (expectedBatter && match.currentBatter !== expectedBatter) issues.push("current-batter-mismatch");
  }
  ["home", "away"].forEach(team => {
    if (typeof TeamRosterFoundation !== "undefined") {
      issues.push(...TeamRosterFoundation.validateActiveDefense(match?.rosters?.[team]).issues.map(issue => `${team}-${issue}`));
    }
    const index = Number(match?.battingOrderIndex?.[team]);
    const length = match?.rosters?.[team]?.lineup?.length || 0;
    if (!Number.isInteger(index) || index < 0 || (length && index >= length)) issues.push(`${team}-batting-order-index-invalid`);
    const score = Number(match?.scores?.[team]);
    if (!Number.isFinite(score) || score < 0) issues.push(`${team}-score-invalid`);
  });
  return Object.freeze(issues);
}

function applyHighSchoolSimulatedPlateAppearance(match, result, batterId, offenseTeam, supportedOutType = null) {
  const runnersBefore = match.runners.slice(0, 3);
  const [first, second, third] = runnersBefore;
  let proposedRunnersAfter = runnersBefore.slice(0, 3);
  const scoringAttempts = [];
  const attemptScore = (runnerId, timing = "beforeThirdOut") => {
    if (runnerId) scoringAttempts.push({ runnerId, timing });
  };
  let outsCreated = 0;
  if (["out", "strikeout"].includes(result)) {
    outsCreated = 1;
  } else if (result === "productiveOut") {
    outsCreated = 1;
    if (match.outs + outsCreated < 3) {
      if (third) attemptScore(third);
      proposedRunnersAfter = [null, first, second];
    }
  } else if (result === "walk") {
    let nextSecond = second;
    let nextThird = third;
    if (first) {
      if (second) {
        if (third) attemptScore(third);
        nextThird = second;
      }
      nextSecond = first;
    }
    proposedRunnersAfter = [batterId, nextSecond, nextThird];
  } else if (result === "single") {
    if (third) attemptScore(third);
    proposedRunnersAfter = [batterId, first, second];
  } else if (result === "double") {
    if (third) attemptScore(third);
    if (second) attemptScore(second);
    proposedRunnersAfter = [null, batterId, first];
  } else if (result === "triple") {
    [first, second, third].forEach(runnerId => attemptScore(runnerId));
    proposedRunnersAfter = [null, null, batterId];
  } else if (result === "homeRun") {
    [first, second, third, batterId].forEach(runnerId => attemptScore(runnerId));
    proposedRunnersAfter = [null, null, null];
  }
  const thirdOutResolution = resolveHighSchoolThirdOutIntegrity({
    outsBefore: match.outs,
    outsCreated,
    runnersBefore,
    proposedRunnersAfter,
    scoringAttempts,
    thirdOutType: outsCreated > 0 ? HIGH_SCHOOL_THIRD_OUT_TYPES.batterRunnerBeforeFirst : HIGH_SCHOOL_THIRD_OUT_TYPES.none,
    orderedRetirements: outsCreated ? [{runnerId:batterId,targetBase:supportedOutType === "caughtBallOut" ? "caught" : "first",
      outType:supportedOutType || (result === "strikeout" ? "strikeout" : "batterRunnerBeforeFirst"),sequence:1,
      forceStateAtRetirement:{forceTargets:{}},isBatterRunner:true,beforeFirst:!supportedOutType && result !== "strikeout"}] : []
  });
  match.outs = thirdOutResolution.outsAfter;
  const scoringEvents = thirdOutResolution.legalScoringRunnerIds.map(runnerId =>
    scoreHighSchoolMatchRunner(match, runnerId, offenseTeam, result, { deferEvent: true })
  ).filter(Boolean);
  match.runners = thirdOutResolution.basesAfter.slice();
  if (thirdOutResolution.halfInningEnded) {
    match.pendingHalfInningTermination = JSON.parse(JSON.stringify(thirdOutResolution));
  }
  syncHighSchoolMatchPlayerRunnerLocation(match);
  const scoringRunnerIds = scoringEvents.map(event => event.runnerId);
  const runnerChanges = runnersBefore.map((runnerId, index) => {
    if (!runnerId) return null;
    const nextIndex = match.runners.indexOf(runnerId);
    return {
      runnerId,
      from: index + 1,
      to: scoringRunnerIds.includes(runnerId) ? "home"
        : nextIndex >= 0 ? nextIndex + 1
          : thirdOutResolution.halfInningEnded ? "halfInningEnd" : "out"
    };
  }).filter(Boolean);
  const batterIndex = match.runners.indexOf(batterId);
  runnerChanges.push({ runnerId: batterId, from: "batter", to: batterIndex >= 0 ? batterIndex + 1 : result === "homeRun" ? "home" : "out" });
  scoringEvents.forEach(event => recordHighSchoolMatchSimulationEvent(match, { ...event, presentationImportance: "hidden" }));
  return Object.freeze({
    runnersBefore: Object.freeze(runnersBefore),
    runnersAfter: Object.freeze(match.runners.slice(0, 3)),
    runnerChanges: Object.freeze(runnerChanges.map(change => Object.freeze(change))),
    scoringRunnerIds: Object.freeze(scoringRunnerIds),
    thirdOutResolution
  });
}

function resolveSimulatedHighSchoolPlateAppearance(match, randomSource = null, options = {}) {
  if (match.completed || match.outs >= 3 || !["home", "away"].includes(match.offenseTeam)) return false;
  // A ground lifecycle owns this PA until its canonical settlement is consumed.
  // Recovery validates the original context before applying recorded execution.
  if (match.activeSituation?.type === "groundBallDefensiveDecision") {
    if (match.activeSituation.lifecycleState === "resolved") return resumeResolvedHighSchoolGroundBallSettlement(match);
    if (!MatchSituationLifecycle.canResumeSimulation(match.activeSituation)) return false;
  }
  const batter = getHighSchoolMatchLineupBatter(match, match.offenseTeam);
  if (!batter || (batter.id === "player" && options.allowPlayer !== true)) return false;
  const capability = getOffensiveSimulationCapability(batter);
  const pitcher = getCurrentHighSchoolMatchDefender(match, match.defenseTeam, "投手");
  if (typeof TeamRosterFoundation !== "undefined" && !pitcher) throw new Error("Active defense integrity failed: missing active pitcher");
  const pitcherCapability = pitcher ? getDefensiveSimulationCapability(pitcher, "投手") : { fielding: 5, arm: 5, decision: 5 };
  const rawSample = typeof randomSource === "function" ? Number(randomSource()) : nextHighSchoolMatchSimulationRandom(match);
  const sample = Math.max(0, Math.min(0.999999, Number.isFinite(rawSample) ? rawSample : 0.5));
  const control = pitcher?.pitchingProfile?.control;
  const identity = `${match.id}|pa-${match.simulationLog?.filter(event => event.type === "plateAppearance").length || 0}|${batter.id}|${pitcher?.id || "missing-pitcher"}`;
  const outcome = AIPlateAppearanceOutcome.resolveCompressedPlateAppearanceOutcome({
    identity, sample, batter: capability,
    pitcher: { pitchingQuality: Number(pitcher?.pitching) || 5, decision: pitcherCapability.decision, control: Number.isFinite(control) ? control : null },
    context: { hasRunner: match.runners.some(Boolean), outs: match.outs, offenseTrailing: match.scores[match.offenseTeam] < match.scores[match.defenseTeam] }
  });
  const result = outcome.result;
  const before = { outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
  const runnerFacts = applyHighSchoolSimulatedPlateAppearance(match, result, batter.id, match.offenseTeam);
  const runsBattedIn = Math.max(0, match.scores[match.offenseTeam] - before.scores[match.offenseTeam]);
  recordHighSchoolMatchPlateAppearanceEvidence(match, batter.id, result, runsBattedIn);
  recordHighSchoolMatchSimulationEvent(match, {
    type: "plateAppearance", inning: match.inning, half: match.half,
    eventClassification: "ordinaryPlay",
    outcomeAuthority: outcome.authority, resolutionMode: outcome.resolutionMode, compressedOutcomeTrace: outcome.trace,
    offenseTeam: match.offenseTeam, batterId: batter.id, result, runsBattedIn,
    currentBatterAfter: getHighSchoolMatchNextLineupBatter(match, match.offenseTeam)?.id || "",
    runnerChanges: runnerFacts.runnerChanges, scoringRunnerIds: runnerFacts.scoringRunnerIds,
    thirdOutResolution: runnerFacts.thirdOutResolution, before,
    after: { outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() }
  });
  advanceHighSchoolMatchBattingOrder(match, match.offenseTeam);
  assertHighSchoolMatchStateIntegrity(match, "plate-appearance");
  return { batterId: batter.id, result };
}

function recordHighSchoolMatchPlateAppearanceEvidence(match, batterId, result, runsBattedIn = 0) {
  const evidence = getHighSchoolMatchPerformanceEvidence(match, batterId);
  if (!evidence) return null;
  evidence.plateAppearances += 1;
  if (["single", "double", "triple", "homeRun"].includes(result)) evidence.hits += 1;
  if (result === "walk") evidence.walks += 1;
  evidence.runsBattedIn += Math.max(0, Number(runsBattedIn) || 0);
  return evidence;
}

function recordHighSchoolRoutinePlateAppearance(match, batterId, result, before, after, runsBattedIn = 0, runnerFacts = {}) {
  recordHighSchoolMatchPlateAppearanceEvidence(match, batterId, result, runsBattedIn);
  return recordHighSchoolMatchSimulationEvent(match, {
    type: "plateAppearance",
    presentationImportance: "hidden",
    meaningful: false,
    eventClassification: "playerRoutinePlay",
    ...(runnerFacts.outcomeAuthority === "existingOrdinaryPhysicalOutcome" ? {
      eventClassification: "ordinaryPlay", outcomeAuthority: runnerFacts.outcomeAuthority,
      physicalTruth: JSON.parse(JSON.stringify(runnerFacts.physicalTruth)), physicalIdentity: runnerFacts.physicalTruth?.identity || null,
      defensiveOpportunity: runnerFacts.defensiveOpportunity ? JSON.parse(JSON.stringify(runnerFacts.defensiveOpportunity)) : null
    } : {}),
    inning: after.inning,
    half: after.half,
    offenseTeam: after.half === "上" ? "away" : "home",
    batterId,
    result,
    runsBattedIn,
    ...(runnerFacts.scorerFacts ? { scorerErrorOwner: { playIdentity: runnerFacts.scorerFacts.playIdentity,
      authority: "defensiveActionAttribution" } } : {}),
    runnerChanges: Array.isArray(runnerFacts.runnerChanges) ? runnerFacts.runnerChanges : [],
    scoringRunnerIds: Array.isArray(runnerFacts.scoringRunnerIds) ? runnerFacts.scoringRunnerIds : [],
    thirdOutResolution: runnerFacts.thirdOutResolution || null,
    before: { outs: before.outs, scores: { ...before.scores }, runners: before.runners.slice() },
    after: { outs: after.outs, scores: { ...after.scores }, runners: after.runners.slice() }
  });
}

function advanceHighSchoolMatchAfterHalfInning(match) {
  if (match.outs < 3) return false;
  const completedInning = match.inning;
  const completedHalf = match.half;
  const completedOffenseTeam = match.offenseTeam;
  const completedRuns = ensureHighSchoolMatchLineScoreInning(match, completedOffenseTeam, completedInning);
  const terminalState = match.pendingHalfInningTermination || null;
  const playerStranded = Array.isArray(terminalState?.strandedRunnerIds)
    ? terminalState.strandedRunnerIds.includes("player") : match.runners.includes("player");
  recordHighSchoolMatchSimulationEvent(match, {
    type: "halfInningEnd", inning: completedInning, half: completedHalf,
    offenseTeam: completedOffenseTeam, runsScored: completedRuns,
    outs: 3, playerStranded, scores: match.scores,
    thirdOutType: terminalState?.thirdOutType || HIGH_SCHOOL_THIRD_OUT_TYPES.none,
    scoringAllowed: terminalState?.scoringAllowed !== false,
    basesBefore: terminalState?.basesBefore || match.runners,
    basesAfter: [null, null, null],
    halfInningTransition: "completed",
    assignment: `${completedInning}局${completedHalf}三出局，半局結束。`
  });
  const nextHalf = completedHalf === "上" ? "下" : "上";
  const nextInning = completedHalf === "上" ? completedInning : completedInning + 1;
  const nextOffenseTeam = nextHalf === "上" ? "away" : "home";
  const nextDefenseTeam = nextOffenseTeam === "away" ? "home" : "away";
  const nextBatter = getHighSchoolMatchLineupBatter(match, nextOffenseTeam)?.id || "";
  Object.assign(match, {
    inning: nextInning,
    half: nextHalf,
    outs: 0,
    runners: [null, null, null],
    offenseTeam: nextOffenseTeam,
    defenseTeam: nextDefenseTeam,
    currentBatter: nextBatter,
    halfInningResolved: false
  });
  match.pendingHalfInningTermination = null;
  match.tiebreakHalfInitialization = null;
  initializeHighSchoolExtraInningTiebreakHalf(match);
  syncHighSchoolMatchPlayerRunnerLocation(match);
  recordHighSchoolMatchSimulationEvent(match, {
    type: "sideChange", inning: match.inning, half: match.half,
    offenseTeam: match.offenseTeam, outs: 0, scores: match.scores,
    assignment: `攻守交換，進入${match.inning}局${match.half}。`
  });
  assertHighSchoolMatchStateIntegrity(match, "side-change");
  return true;
}

function initializeHighSchoolExtraInningTiebreakHalf(match) {
  const placement = resolveHighSchoolExtraInningTiebreakPlacement(match);
  if (!placement) return false;
  const marker = match.tiebreakHalfInitialization;
  if (marker?.applied && marker.inning === match.inning && marker.half === match.half) return false;
  if (match.outs !== 0 || match.runners.some(Boolean)) throw new Error("Tiebreak half already has live state");
  match.runners[placement.runnerBase - 1] = placement.runnerId;
  match.tiebreakHalfInitialization = {
    inning: match.inning, half: match.half, applied: true,
    runnerId: placement.runnerId, lineupSlot: placement.lineupSlot,
    earnedRunTreatment: placement.earnedRunTreatment, runnerResponsibilityActive: true
  };
  syncHighSchoolMatchPlayerRunnerLocation(match);
  return true;
}

function recordHighSchoolMatchSimulationEvent(match, event) {
  if (event.type === "plateAppearance" && /Pending$/.test(event.result || "")) throw new Error("Pending defense cannot enter the official PA ledger");
  if (!Array.isArray(match.simulationLog)) match.simulationLog = [];
  const defaultImportance = getHighSchoolMatchEventPresentationImportance(event);
  const record = Object.assign({ sequence: match.simulationLog.length, presentationImportance: defaultImportance }, event);
  if (record.scores) record.scores = { ...record.scores };
  if (record.runners) record.runners = record.runners.slice(0, 3);
  if (Array.isArray(record.runnerChanges)) record.runnerChanges = record.runnerChanges.map(change => ({ ...change }));
  if (Array.isArray(record.scoringRunnerIds)) record.scoringRunnerIds = record.scoringRunnerIds.slice();
  record.presentationSnapshot = createHighSchoolMatchPresentationSnapshot(match, record);
  match.simulationLog.push(record);
  if (typeof MatchGameRecord !== "undefined") {
    if (!match.gameRecord) {
      match.gameRecord = MatchGameRecord.createGameRecord({
        gameId: match.id,
        competitionEditionId: match.competitionEditionId,
        competitionEntryId: match.competitionEntryId,
        homeTeamId: match.matchContext?.homeTeamId || match.competitionTeamId || match.rosters?.home?.teamRoster?.teamId || "home",
        awayTeamId: match.matchContext?.awayTeamId || match.rosters?.away?.teamRoster?.teamId || "away",
        inningsScheduled: match.regulationInnings,
        rosters: match.rosters
      });
    }
    MatchGameRecord.recordEvent(match.gameRecord, record, {
      rosters: match.rosters,
      playerId: "player",
      playerTeam: getHighSchoolPlayerTeamSide(match),
      playerRole: match.playerLineupStatus || match.role,
      playerPosition: match.playerFieldingAssignment || match.currentFieldingPosition || match.position
    });
  }
  return record;
}

function getHighSchoolDefensiveForceState(match) {
  if (typeof ForceAdvancement !== "undefined") {
    const forceChain = ForceAdvancement.buildInitialLiveBallForceChain({
      runners: match.runners,
      batterRunnerId: match.currentBatter || "batter-runner"
    });
    return ForceAdvancement.deriveCompatibilityForceState(forceChain, { outs: match.outs });
  }
  const occupied = match.runners.map(Boolean);
  return Object.freeze({
    first: occupied[0],
    second: occupied[1],
    third: occupied[2],
    forceAtSecond: occupied[0],
    forceAtThird: occupied[0] && occupied[1],
    forceAtHome: occupied[0] && occupied[1] && occupied[2],
    doublePlayEligible: occupied[0] && match.outs < 2
  });
}

function getHighSchoolDefensiveOpportunity(match, physicalTruth) {
  if (typeof DefensiveOpportunityFoundation === "undefined") return null;
  const prior = match?.groundBallInPlayState;
  const samePhysical = prior?.physicalTruth?.identity === physicalTruth?.identity;
  const historical = samePhysical && (prior?.defensiveOpportunity || (prior?.defensiveAccess?.reachResolution
    ? { topologyVersion: "regulation-coarse-zones-v1" } : null));
  const responsibility = DefensiveOpportunityFoundation.deriveGroundResponsibility?.(physicalTruth,
    DefensiveOpportunityFoundation.FIRST_BASE_GROUND_TOPOLOGY_VERSION);
  // The classifier is shared by player and NPC assignments. Unchanged SS/2B
  // lanes keep their existing execution identities; saved lanes retain their version.
  const topologyVersion = historical ? historical.topologyVersion
    : responsibility?.primaryPosition === "1B" ? DefensiveOpportunityFoundation.FIRST_BASE_GROUND_TOPOLOGY_VERSION
      : responsibility?.primaryPosition === "3B" ? DefensiveOpportunityFoundation.GROUND_TOPOLOGY_VERSION : undefined;
  return DefensiveOpportunityFoundation.resolveDefensiveOpportunity({
    physicalTruth, activeRoster: match?.rosters?.[match.defenseTeam], topologyVersion
  });
}

function getHighSchoolReachAccess(match, physicalTruth, opportunity, defenderContext) {
  if (typeof DefensiveReachSecureFoundation === "undefined" || !opportunity?.supported) return null;
  const actor = TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], opportunity.primaryPosition);
  const source = actor.id === "player" ? player : actor;
  const adapted = getDefensiveSimulationCapability(source, opportunity.primaryPosition, match);
  const capabilities = { defenderId: actor.id,
    reaction: defenderContext.reaction ?? adapted.reaction,
    range: defenderContext.range ?? adapted.range,
    mobility: getOffensiveSimulationCapability(source).speed,
    fielding: defenderContext.fielding ?? defenderContext.catching ?? adapted.fielding,
    catching: defenderContext.catching ?? defenderContext.fielding ?? adapted.fielding };
  const reach = DefensiveReachSecureFoundation.resolveReach({ physicalTruth, opportunity,
    activeRoster: match.rosters[match.defenseTeam], capabilities, roll: defenderContext.reachRoll });
  return { ...DefensiveReachSecureFoundation.projectAccess(reach), secureCapabilities: capabilities };
}

function getHighSchoolPhysicalDefensePlayerContext(match, physicalTruth, defenderContext, options = {}) {
  const opportunity = getHighSchoolDefensiveOpportunity(match, physicalTruth);
  if (!opportunity) return defenderContext; // Pre-foundation isolated harness compatibility.
  if (opportunity.bindingStatus === "invalid") throw new Error("Active defense integrity failed: defensive opportunity binding");
  const ownsGroundSlice = opportunity.supported && opportunity.primaryDefenderId === "player"
    && (opportunity.primaryPosition === "2B" || (["SS", "3B", "1B"].includes(opportunity.primaryPosition) && physicalTruth.ballType === "groundBall"));
  const firstBase = TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], "1B");
  const continuation = options.incomingContinuation;
  const liveContinuation = continuation?.version === "incoming-continuation-admission-v1"
    && continuation.matchId === match.id && continuation.batterId === match.currentBatter
    && continuation.inning === match.inning && continuation.half === match.half
    && continuation.offenseTeam === match.offenseTeam && continuation.defenseTeam === match.defenseTeam
    && continuation.outs === match.outs && JSON.stringify(continuation.runners) === JSON.stringify(match.runners);
  const receivesGroundSlice = firstBase?.id === "player" && physicalTruth.ballType === "groundBall"
    && liveContinuation && opportunity.supported && ["SS", "2B", "3B"].includes(opportunity.primaryPosition);
  const npc = receivesGroundSlice ? TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], opportunity.primaryPosition) : null;
  const acquisition = npc ? getDefensiveSimulationCapability(npc, npc.position, match) : defenderContext;
  return { ...defenderContext, ...acquisition, playerPosition: ownsGroundSlice || receivesGroundSlice ? TeamRosterFoundation.POSITION_LABELS[opportunity.primaryPosition] : "",
    defensiveOpportunity: opportunity,
    ...(ownsGroundSlice || receivesGroundSlice ? { reachAccess: getHighSchoolReachAccess(match, physicalTruth, opportunity, acquisition) } : {}) };
}

function resolveHighSchoolCanonicalSecure(match, state, roll) {
  const reachResult = state?.defensiveAccess?.reachResolution;
  if (!reachResult || typeof DefensiveReachSecureFoundation === "undefined") return null;
  return DefensiveReachSecureFoundation.resolveSecure({ physicalTruth: state.physicalTruth,
    opportunity: getHighSchoolDefensiveOpportunity(match, state.physicalTruth),
    activeRoster: match.rosters[match.defenseTeam], capabilities: state.defensiveAccess.secureCapabilities,
    reachResult, roll });
}

function ensureHighSchoolOrdinaryGroundBallInPlayHandoff(match, options = {}) {
  if (!match || typeof BattedBallGroundDefense === "undefined" || typeof OffensivePlateApproach === "undefined") return null;
  if (match.offensiveTacticalActionState?.selectedTacticalAction !== "standardAttack") return null;
  const playerPosition = match.developmentPositionOverride || getHighSchoolInfieldAssignmentPosition(match, player);
  const batter = getHighSchoolMatchSimulationEntity(match, match.currentBatter);
  const paIdentity = `${createHighSchoolOffensiveTacticalIdentity(match)}|ordinary-contact`;
  const existing = BattedBallGroundDefense.normalizeHandoff(match.groundBallInPlayState);
  const existingLineDrive = typeof BattedBallLineDriveDefense !== "undefined"
    ? BattedBallLineDriveDefense.normalizeCatchState(match.lineDriveCatchState) : null;
  const existingFlyBall = typeof BattedBallFlyBallDefense !== "undefined"
    ? BattedBallFlyBallDefense.normalizeFlyBallCatchState(match.flyBallCatchState) : null;
  if (existing?.identity === `${paIdentity}|ground-defense`) {
    validateHighSchoolReceiverSourceMetadata(match);
    if (existing.supported && !existing.settlementApplied) assertHighSchoolGroundParticipant(match);
    match.groundBallInPlayState = existing;
    return existing;
  }
  if (existingLineDrive?.identity === `${paIdentity}|line-drive-catch`) {
    if (existingLineDrive.supported && !existingLineDrive.settlementApplied) assertHighSchoolDetailedResponsibility(match, existingLineDrive.physicalTruth, "2B", "player");
    match.lineDriveCatchState = existingLineDrive;
    return null;
  }
  if (existingFlyBall?.identity === `${paIdentity}|fly-ball-catch`) {
    if (existingFlyBall.supported && !existingFlyBall.settlementApplied) assertHighSchoolDetailedResponsibility(match, existingFlyBall.physicalTruth, existingFlyBall.defenderContext?.position, existingFlyBall.defenderContext?.defenderId);
    match.flyBallCatchState = existingFlyBall;
    return null;
  }
  const defender = {
    ...getDefensiveSimulationCapability(player, "內野手"),
    ...(options.situationOverrides?.playerCapabilities || {})
  };
  const physicalDefenderContext = physicalTruth => getHighSchoolPhysicalDefensePlayerContext(match, physicalTruth, {
    playerPosition, catching: defender.fielding, reaction: defender.reaction, range: defender.range
  }, options);
  const offense = getHighSchoolProvisionalOffensiveTacticalCapabilities(match);
  const initial = OffensivePlateApproach.createPlateAppearanceState({
    paIdentity,
    batterId: match.currentBatter,
    approach: "balancedAttack",
    context: { outs: match.outs, runners: match.runners.slice(), hasRunner: match.runners.some(Boolean) }
  });
  const fixture = options.ordinaryPlateAppearance || {};
  const pitch = fixture.pitch || { pitchLocationClass: "hitterPitch" };
  const pitchOptions = {
    recognitionRoll: fixture.recognitionRoll ?? 0,
    decisionRoll: fixture.decisionRoll ?? 0,
    contactRoll: fixture.contactRoll ?? 0,
    foulRoll: fixture.foulRoll ?? 1,
    physicalRolls: fixture.physicalRolls,
    outcomeRoll: fixture.outcomeRoll,
    physicalOutcomeResolver({ physicalTruth }) {
      const access = BattedBallGroundDefense.resolveGroundBallDefensiveAccess({
        physicalTruth,
        defenderContext: physicalDefenderContext(physicalTruth)
      });
      if (access.supported) return {
        result: "groundBallDefensePending",
        authority: "bbpB1PhysicalDefensePending",
        contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
        resolvedContact: null
      };
      if (typeof BattedBallLineDriveDefense !== "undefined") {
        const airborneContext = BattedBallLineDriveDefense.buildAirborneBallContext(physicalTruth);
        const catchAccess = airborneContext ? BattedBallLineDriveDefense.resolveCatchAccess({
          airborneContext,
          defenderContext: physicalDefenderContext(physicalTruth)
        }) : null;
        const catchWindow = catchAccess ? BattedBallLineDriveDefense.buildCatchTimingWindow({ airborneContext, defensiveAccess: catchAccess }) : null;
        if (catchAccess?.supported && catchWindow?.state !== "expired") return {
          result: "lineDriveCatchPending",
          authority: "bbpB2APhysicalCatchPending",
          contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
          resolvedContact: null
        };
      }
      if (typeof BattedBallFlyBallDefense !== "undefined") {
        const flyBallDefender = getHighSchoolFlyBallDefenderCatchContext(match, physicalTruth, options);
        const flyBallOpportunity = BattedBallFlyBallDefense.buildFlyBallCatchOpportunity({
          identity: `${paIdentity}|fly-ball-catch`, physicalTruth, runners: [], outs: match.outs,
          runnerEntities: [], defenderContext: flyBallDefender
        });
        if (flyBallOpportunity?.supported) return {
