    const candidates = [];
    const retire = (runnerId, targetBase, outType) => { if (runnerId) candidates.push({ runnerId, targetBase, outType, sequence: candidates.length + 1 }); };
    if (suppliedRetirements) candidates.push(...clone(suppliedRetirements));
